/**
 * Generates every framework's components from the core's widgets, into each framework's package, formatted by oxfmt.
 * With `--check`, generates them aside and fails if any package's generated files differ from them.
 */

import { describe } from '../packages/codegen/src/components.js'
import { react, vue } from '../packages/codegen/src/frameworks.js'
import { load } from '../packages/codegen/src/program.js'

const ROOT = new URL('..', import.meta.url).pathname
const HEADER = '// Generated by @pterror/interact-codegen from @pterror/interact-core. Do not edit.'

const { diagnostics, widgets } = describe(
  load(`${ROOT}packages/core/tsconfig.json`),
  `${ROOT}packages/core/src/index.js`,
  ROOT,
)
for (const diagnostic of diagnostics) {
  console.error(diagnostic)
}
if (diagnostics.length > 0) {
  process.exit(1)
}

/** @type {readonly (readonly [string, ReadonlyMap<string, string>])[]} */
const packages = [
  ['react', react(widgets, HEADER)],
  ['vue', vue(widgets, HEADER)],
]

const checking = process.argv.includes('--check')
const made = await Bun.$`mktemp -d -t interact-components-XXXXXX`.text()
const staging = made.trim()
/** @type {string[]} */
const stale = []
/** @type {readonly Readonly<{ path: string, text: string }>[]} */
const outputs = packages.flatMap((made_) => {
  const [name, files] = made_
  return Array.from(files.keys(), (path) => ({ path: `${name}/${path}`, text: files.get(path) ?? '' }))
})
await Promise.all(outputs.map(async (output) => Bun.write(`${staging}/${output.path}`, output.text)))
await Bun.$`${ROOT}node_modules/.bin/oxfmt --config=${ROOT}.oxfmtrc.json .`.cwd(staging).quiet()
await Promise.all(
  outputs.map(async (output) => {
    const { path } = output
    const target = `${ROOT}packages/${path.replace('/', '/src/')}`
    const text = await Bun.file(`${staging}/${path}`).text()
    const existing = Bun.file(target)
    const now = (await existing.exists()) ? await existing.text() : undefined
    if (now === text) {
      return
    }
    if (checking) {
      stale.push(target.slice(ROOT.length))
    } else {
      await Bun.write(target, text)
    }
  }),
)
await Bun.$`rm -rf ${staging}`
if (stale.length > 0) {
  console.error(`Out of date (run bun run components):\n${stale.join('\n')}`)
  process.exitCode = 1
}
